('00000000-0000-0000-0000-000000000000', 'Kann der Betrieb mich ohne Grund kündigen?', 2, '[{"text": "Nein", "correct": true, "because": "Kündigungsfrist oder Grund nötig"}, {"text": "Ja", "correct": false, "because": "Gesetzlicher Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss der Betrieb mich ordnungsgemäß ausbilden?', 2, '[{"text": "Ja", "correct": true, "because": "Pflicht nach BBiG"}, {"text": "Nein", "correct": false, "because": "Vertragsverpflichtung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Betrieb verpflichtet, mir Vergütung zu zahlen?', 2, '[{"text": "Ja", "correct": true, "because": "Gesetzliche Pflicht"}, {"text": "Nein", "correct": false, "because": "Vertraglich geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Könnte der Betrieb mich zwingen, jeden Tag Überstunden zu machen?', 2, '[{"text": "Nein", "correct": true, "because": "Jugendarbeitsschutz begrenzt"}, {"text": "Ja", "correct": false, "because": "Nur mit Vereinbarung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sag mir nochmal: Muss der Betrieb meinen Vertrag bei der IHK melden?', 2, '[{"text": "Ja", "correct": true, "because": "Registrierungspflicht"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann der Betrieb meinen Urlaub komplett verbieten?', 2, '[{"text": "Nein", "correct": true, "because": "Gesetzlicher Anspruch"}, {"text": "Ja", "correct": false, "because": "Nur begründete Ablehnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der Betrieb verpflichtet, mir Arbeitskleidung zu stellen?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei Gefahr oder Vorschrift"}, {"text": "Ja", "correct": false, "because": "Nicht generell Pflicht"}]'),
