-- Single-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Pflicht hat der Betrieb gegenüber mir als Azubi?', 2, '[{"text": "Ausbildung gewährleisten", "correct": true, "because": "Kernaufgabe"}, {"text": "Urlaub verbieten", "correct": false, "because": "Illegal"}, {"text": "Kündigung erleichtern", "correct": false, "because": "Kein Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Meine Chefin sagt, ich muss länger bleiben. Was darf der Betrieb verlangen?', 3, '[{"text": "Überstunden in Grenzen", "correct": true, "because": "Mit Rücksicht auf JArbSchG"}, {"text": "Unbegrenzte Arbeit", "correct": false, "because": "Gesetzeswidrig"}, {"text": "Nur Wochenenden", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht hat der Betrieb bei meiner Ausbildung?', 2, '[{"text": "Anweisungen geben", "correct": true, "because": "Weisungsrecht"}, {"text": "Vergütung streichen", "correct": false, "because": "Pflicht bleibt"}, {"text": "Prüfungen abhalten", "correct": false, "because": "IHK-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Der Abteilungsleiter will meinen Urlaub ablehnen. Wann darf der Betrieb das?', 3, '[{"text": "Bei dringenden betrieblichen Gründen", "correct": true, "because": "Gesetzlich erlaubt"}, {"text": "Immer", "correct": false, "because": "Anspruch bleibt"}, {"text": "Nie", "correct": false, "because": "Bedingte Ablehnung möglich"}]'),
-- Multiple-Choice-Fragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten hat der Betrieb gegenüber einem Azubi?', 4, '[{"text": "Vergütung zahlen", "correct": true, "because": "Gesetzlich"}, {"text": "Ausbildung fördern", "correct": true, "because": "Vertraglich"}, {"text": "Urlaub gewähren", "correct": true, "because": "Pflicht"}, {"text": "Freizeit planen", "correct": false, "because": "Privatangelegenheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte hat der Betrieb in der Ausbildung?', 3, '[{"text": "Arbeitszeiten festlegen", "correct": true, "because": "Organisation"}, {"text": "Anweisungen erteilen", "correct": true, "because": "Weisungsrecht"}, {"text": "Kündigungsschutz beachten", "correct": true, "because": "Gesetzlich gebunden"}, {"text": "Prüfungen bewerten", "correct": false, "because": "IHK-Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Wir haben Streit über meine Ausbildung. Was muss der Betrieb tun?', 3, '[{"text": "Ausbildungsplan einhalten", "correct": true, "because": "Verpflichtung"}, {"text": "IHK informieren", "correct": true, "because": "Bei Problemen"}, {"text": "Konflikt klären", "correct": true, "because": "Pflicht zur Zusammenarbeit"}, {"text": "Mich ignorieren", "correct": false, "because": "Verstoß"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss der Betrieb bei meiner Vergütung beachten?', 4, '[{"text": "Pünktliche Zahlung", "correct": true, "because": "Gesetzlich"}, {"text": "Tarifbindung prüfen", "correct": true, "because": "Falls gebunden"}, {"text": "Mindeststandards einhalten", "correct": true, "because": "Regelung"}, {"text": "Zahlung nach Lust", "correct": false, "because": "Nicht erlaubt"}]'),
-- Kombinationsfragen (4 Stück, 20%)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der Betrieb muss mich ausbilden. b) Er kann meinen Urlaub immer ablehnen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ausbildung ja, Urlaub nur bedingt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Betrieb zahlt meine Vergütung. b) Er darf mich ohne Kündigungsfrist entlassen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vergütung ja, Kündigung geregelt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Der Betrieb meldet meinen Vertrag bei der IHK. b) Er muss mir jeden Tag freigeben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Meldung ja, Freizeit nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Der Betrieb hat Weisungsrecht. b) Er kann meine Ausbildung ignorieren.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Weisung ja, Ausbildung Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

